// Simulate temperature for Zone 1 — Leopard Highlands (Arabian Leopard)
let rand = Math.random();
let temperature;
if (rand < 0.60) {
    temperature = Math.floor(Math.random() * (42 - 25 + 1)) + 25;
} else if (rand < 0.85) {
    temperature = Math.floor(Math.random() * (45 - 43 + 1)) + 43;
} else {
    temperature = Math.floor(Math.random() * (52 - 46 + 1)) + 46;
}
msg.payload = JSON.stringify({ temperature: temperature });
msg.topic = "wildlife/zone1/temperature";
return msg;

// Simulate water level for Zone 1 — Leopard Highlands (Arabian Leopard)
let waterRand = Math.random();
let water_level;
if (waterRand < 0.55)      { water_level = "high"; }
else if (waterRand < 0.80) { water_level = "medium"; }
else if (waterRand < 0.92) { water_level = "low"; }
else                       { water_level = "empty"; }
msg.payload = JSON.stringify({ water_level: water_level });
msg.topic = "wildlife/zone1/water";
return msg;

// Simulate motion for Zone 1 — Leopard Highlands (Arabian Leopard)
let motion = Math.random() > 0.40 ? 1 : 0;
let type = "none";
if (motion === 1) {
    type = Math.random() > 0.85 ? "intruder" : "animal";
}
msg.payload = JSON.stringify({ motion: motion, type: type });
msg.topic = "wildlife/zone1/motion";
return msg;

// Evaluate temperature threshold for Zone 1 — Leopard Highlands
let data = msg.payload;
if (typeof data === "string") { try { data = JSON.parse(data); } catch(e) { return null; } }
let temp = data.temperature;
let status = "STABLE";
let alert  = "✅ Temperature within safe range: " + temp + "°C";
if (temp > 45) {
    status = "CRITICAL";
    alert  = "🔴 CRITICAL — Temperature at " + temp + "°C. Immediate cooling required!";
} else if (temp > 42) {
    status = "WARNING";
    alert  = "🟡 WARNING — Temperature at " + temp + "°C. Approaching unsafe threshold.";
}
// Store in flow context for combined alert logic
flow.set("z1_temp_status", status);
flow.set("z1_temp_alert",  alert);
flow.set("z1_temp_value",  temp);
// Pass temperature value to gauge
msg.payload = temp;
msg.status  = status;
msg.alert   = alert;
return msg;

// Evaluate water level threshold for Zone 1 — Leopard Highlands
let data = msg.payload;
if (typeof data === "string") { try { data = JSON.parse(data); } catch(e) { return null; } }
let lvl = data.water_level;
let status = "STABLE";
let alert  = "✅ Water supply is adequate: " + lvl;
if (lvl === "empty") {
    status = "CRITICAL";
    alert  = "🔴 CRITICAL — Water source depleted. Animal survival at immediate risk!";
} else if (lvl === "low") {
    status = "WARNING";
    alert  = "🟡 WARNING — Water level is low. Refill stations required soon.";
}
flow.set("z1_water_status", status);
flow.set("z1_water_alert",  alert);
let icons = { high:"💧💧💧 High", medium:"💧💧 Medium", low:"💧 Low ⚠️", empty:"❌ Empty — CRITICAL" };
msg.payload = icons[lvl] || lvl;
msg.status  = status;
msg.alert   = alert;
return msg;

// Evaluate motion/intruder threshold for Zone 1 — Leopard Highlands
let data = msg.payload;
if (typeof data === "string") { try { data = JSON.parse(data); } catch(e) { return null; } }
let motion = data.motion;
let type   = data.type || "none";
let status = "STABLE";
let alert  = "⚪ No motion detected in zone.";
if (motion === 1) {
    if (type === "intruder") {
        status = "CRITICAL";
        alert  = "🔴 CRITICAL — Unauthorized intruder detected in Zone 1 — Leopard Highlands! Ranger dispatch required.";
    } else {
        alert = "🐾 Animal activity detected in zone. Normal behaviour.";
    }
}
flow.set("z1_motion_status", status);
flow.set("z1_motion_alert",  alert);
let icons = { none:"⚪ No Motion Detected", animal:"🐾 Animal Activity Detected", intruder:"🚨 INTRUDER DETECTED" };
msg.payload = icons[type] || icons["none"];
msg.status  = status;
msg.alert   = alert;
return msg;

// Aggregate all sensor statuses into a single zone status for Zone 1 — Leopard Highlands
// Priority: CRITICAL > WARNING > STABLE
let statuses = [
    flow.get("z1_temp_status")   || "STABLE",
    flow.get("z1_water_status")  || "STABLE",
    flow.get("z1_motion_status") || "STABLE"
];
let alerts = [
    flow.get("z1_temp_alert")   || "",
    flow.get("z1_water_alert")  || "",
    flow.get("z1_motion_alert") || ""
];

let finalStatus = "STABLE";
let finalAlert  = "✅ All conditions within safe parameters.";

if (statuses.includes("CRITICAL")) {
    finalStatus = "CRITICAL";
    finalAlert  = alerts[statuses.indexOf("CRITICAL")];
} else if (statuses.includes("WARNING")) {
    finalStatus = "WARNING";
    finalAlert  = alerts[statuses.indexOf("WARNING")];
}

let statusIcon = { STABLE:"🟢 STABLE", WARNING:"🟡 WARNING", CRITICAL:"🔴 CRITICAL" };

// Output 1: status display text
let m1 = { payload: statusIcon[finalStatus] };
// Output 2: alert message text
let m2 = { payload: finalAlert };
// Output 3: formatted MQTT alert JSON
let m3 = { payload: JSON.stringify({
    zone:   "Zone 1 — Leopard Highlands",
    status: finalStatus,
    alert:  finalAlert,
    time:   new Date().toISOString()
}) };
return [m1, m2, m3];

